from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_result, log_exception, log_iteration
from taf.rfrl.procedures.resources.python.exceptions import PowerDiffBelowThreshold, NoCenterFreqForGivenNRARFCN


@log_input_and_output
def measure_power_diff(
    test_model, analyzer, cntr_freq, threshold=30, measures=50, window_size=10
):
    """
    Function measures absolute power difference on test module via signal analyzer on given
    center frequency. It splits measures parameter by window_size to obtain measures/window_sizes
    means in power difference of signal. It is not necessary to provide number of measures divisible
    by window_size, as the method handles it, but it is welcome. All obtained means have to be
    greater than provided threshold, as it is obliged to have stable power on signal.
    :param test_model: test module You want to measure
    :type test_model: str
    :param analyzer: alias of created analyzer object
    :type analyzer: Keysight Analyzer object from taf.hw.signal_analyzer
    :param cntr_freq: center frequency parameter used in setting up the analyzer
    :type cntr_freq: float
    :param threshold: threshold wanted to reach to pass channel power test
    :type threshold: int
    :param measures: number of direct delta measures user want to perform.
    :type measures: int
    :param window_size: Size of the window from which we will calculate mean to compare
    it with provided threshold.
    :type window_size: int
    :return: Boolean True or raise Exception
    :rtype: Bool/Exception
    :raises: PowerDiffBelowThreshold is raised if threshold is not reached by any of the measure.
    :raises: ValueError if we provide negative measures or window_size parameter (or non-int).
    """
    threshold = int(threshold)
    test_model = str(test_model)
    iterations, window_size = _format_iterations_for_measurements(measures, window_size)
    ref_freq = float(cntr_freq) + 0.5

    cntr_freq_measurements = []
    ref_freq_measurements = []

    for iteration in range(int(iterations)):
        for measure in range(window_size):
            measurement = _get_measurements(analyzer, cntr_freq, ref_freq)
            cntr_freq_measurements.append(measurement[0])
            ref_freq_measurements.append(measurement[1])

        mean_cntr_freq_measurement = sum(cntr_freq_measurements) / len(cntr_freq_measurements)
        mean_ref_freq_measurement = sum(ref_freq_measurements) / len(ref_freq_measurements)
        mean_delta = abs(mean_cntr_freq_measurement - mean_ref_freq_measurement)

        log_iteration(
            "{0}. measure of mean equals {1} dBm "
            "(the windows size is {2}, mean center freq power is {3}, mean reference signal power is {4})."
            .format(iteration + 1, mean_delta, window_size, mean_cntr_freq_measurement,
                    mean_ref_freq_measurement)
        )

        if test_model.endswith("-TM2"):
            threshold = 1.5
            log_result(
                "Threshold has been decreased to {0} in this particular test "
                "(according to given test module characteristic)".format(threshold)
            )

        if mean_delta < threshold:
            raise PowerDiffBelowThreshold(
                "One of the measures ({0}) did not exceed given threshold ({1}).".format(mean_delta, threshold)
            )

        cntr_freq_measurements = []
        ref_freq_measurements = []

    return True


@log_input_and_output
def unlock_sa(analyzer):
    """
    Delete analyzer object to unlock analyzer after finished test model.
    :param analyzer: signal analyzer object
    """
    if analyzer:
        analyzer.__del__()


@log_input_and_output
def _get_measurements(analyzer, *freqs):
    measurements = []
    for freq in freqs:
        analyzer.set_center_frequency(frequency=freq, unit="GHz")
        measurements.append(analyzer.measure_channel_power())
    return measurements


@log_input_and_output
def _find_desired_row(file_path, nrarfcn):
    with open(file_path, "r") as datafile:
        desired_row = []
        for row in datafile:
            splitted_row = row.split(",")
            if int(splitted_row[0]) == nrarfcn:
                desired_row = splitted_row
        if len(desired_row) == 0:
            raise NoCenterFreqForGivenNRARFCN(
                "Couldn't find center frequency for "
                "given ({0}) nrarfcn".format(nrarfcn)
            )
    return desired_row


@log_input_and_output
def _format_iterations_for_measurements(measures, window_size):
    try:
        measures, window_size = int(measures), int(window_size)
    except ValueError:
        raise ValueError(
            "One of parameter is not integer. \n"
            "measures parameter: {0}. \n"
            "window_size parameter: {1}.".format(measures, window_size)
        )
    if measures < 0 or window_size < 0:
        raise ValueError("Measures or window size can not be negative!")
    if measures < window_size:
        log_exception(
            "Window size for mean is bigger than the number of expected measures! \n"
            "Number of measures have decreased to 1, to the size"
            "of window size provided by user ({0} direct delta measures".format(
                window_size
            )
        )
        iterations = 1
    elif measures % window_size != 0:
        iterations = measures % window_size
        log_exception(
            "Measures number ({0}) is not multiple of window size ({1}), "
            "so it has been degraded to the smallest multiple {2}".format(
                measures, window_size, iterations * window_size
            )
        )
    else:
        iterations = measures / window_size
    return iterations, window_size


@log_input_and_output
def _extract_desired_center_freq(rf_mode, desired_row):
    if rf_mode == "OTA":
        return float(desired_row[1]) / 1000
    elif rf_mode == "CONDUCTED":
        return float(desired_row[2]) / 1000
    else:
        raise ValueError("Unsupported RF mode")
